n(34px,80%);background:linear-gradient(180deg,#4aa1e4,#1769aa);border-radius:6px 6px 0 0;min-height:2px}.barvalue{font-size:10px;color:#52677e}.barlabel{font-size:10px;color:var(--muted);margin-top:7px}.chartnote{margin-top:12px;font-size:12px;color:var(--muted)}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:480px}th,td{text-align:left;padding:11px;border-bottom:1px solid #edf1f6}th{font-size:11px;text-transform:uppercase;color:var(--muted);background:#f8fafc}.callout{border:1px solid #cfe2f4;background:#f0f7fd;border-radius:12px;padding:15px;margin-top:16px}.callout strong{display:block;color:#174c7c;margin-bottom:4px}.negative{color:var(--red)}.positive{color:var(--green)}.footer{font-size:12px;color:var(--muted);margin:16px 0 28px}@media(max-width:850px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.two{grid-template-columns:1fr}.wrap{padding:0 12px}.title h1{font-size:21px}}@media(max-width:420px){.grid{grid-template-columns:1fr 1fr}.card{padding:13px}.value{font-size:21px}.details{gap:11px}}
